/**
 * Suspension: a suspended member keeps their membership, role and seat, but
 * cannot act, receives nothing, cannot be given new work or mentioned, and comes
 * back intact when reinstated.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as activityService from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as digestService from "@/server/services/digest-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as memberService from "@/server/services/member-service";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as sessionService from "@/server/services/session-service";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { NotFoundError } from "@/server/services/_support";
import { MemberSuspendedError } from "@/server/services/member-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { MemberId, UserId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";
import type { TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";

let cleanup: () => void;
let detachActivity: Unsubscribe;
let staffCount = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = activityService.registerActivityListeners();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

/** Records every payload published on `type` until `stop()` is called. */
function recordEvents(type: TaskflowEventType) {
  const seen: unknown[] = [];
  const stop: Unsubscribe = subscribe(type, (payload) => {
    seen.push(payload);
  });
  return { seen, stop };
}

async function memberIdOf(tenant: Tenant, userId: UserId): Promise<MemberId> {
  const member = await memberRepo.findMember(tenant.org.id, userId);
  if (!member) throw new Error("fixture member missing");
  return member.id;
}

/**
 * A platform-staff actor acting in `tenant` at `role`. Staff pass `can()`, so
 * this is how the last-owner cases get an owner to act on the sole owner: every
 * other actor is either that owner or ranked below owner.
 */
async function staffActor(tenant: Tenant, role: Role): Promise<Actor> {
  staffCount += 1;
  const staff = await userRepo.insertUser({
    email: `staff${staffCount}@${tenant.org.slug}.test`,
    name: "Platform staff",
    passwordHash: "seed",
  });
  return { userId: staff.id, orgId: tenant.org.id, role, isPlatformStaff: true };
}

describe("services/member-service suspension", () => {
  describe("suspending and reinstating", () => {
    it("keeps the membership, role and seat of a suspended member", async () => {
      const tenant = await createTenant("suspend-seat", "growth");
      const adminId = await memberIdOf(tenant, tenant.userIds.admin);

      const suspended = await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: adminId,
      });

      expect(suspended).toMatchObject({ id: adminId, role: "admin", status: "suspended" });
      await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(4);
      await expect(usageRepo.recomputeUsage(tenant.org.id)).resolves.toMatchObject({
        seatsUsed: 4,
      });
    });

    it("emits member.suspended and records it in the audit log", async () => {
      const tenant = await createTenant("suspend-audit", "growth");
      const viewerId = await memberIdOf(tenant, tenant.userIds.viewer);
      const events = recordEvents("member.suspended");

      await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      events.stop();

      expect(events.seen).toEqual([
        expect.objectContaining({
          orgId: tenant.org.id,
          actorId: tenant.userIds.owner,
          memberId: viewerId,
          userId: tenant.userIds.viewer,
        }),
      ]);

      const page = await activityService.listActivity(tenant.actors.owner, {
        orgId: tenant.org.id,
        action: ["member.suspended"],
        limit: 25,
        cursor: null,
      });
      expect(page.items).toHaveLength(1);
      expect(page.items[0]).toMatchObject({
        action: "member.suspended",
        actorId: tenant.userIds.owner,
        subjectKind: "member",
        subjectId: viewerId,
      });
    });

    it("emits member.reinstated and records it in the audit log", async () => {
      const tenant = await createTenant("reinstate-audit", "growth");
      const viewerId = await memberIdOf(tenant, tenant.userIds.viewer);
      await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      const events = recordEvents("member.reinstated");

      const reinstated = await memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      events.stop();

      expect(reinstated.status).toBe("active");
      expect(events.seen).toEqual([
        expect.objectContaining({ actorId: tenant.userIds.owner, memberId: viewerId }),
      ]);

      const page = await activityService.listActivity(tenant.actors.owner, {
        orgId: tenant.org.id,
        action: ["member.reinstated"],
        limit: 25,
        cursor: null,
      });
      expect(page.items).toHaveLength(1);
      expect(page.items[0]).toMatchObject({
        actorId: tenant.userIds.owner,
        subjectKind: "member",
        subjectId: viewerId,
      });
    });

    it("refuses self-suspension and suspending a member ranked above you, publishing nothing", async () => {
      const tenant = await createTenant("suspend-refusals", "growth");
      const ownerId = await memberIdOf(tenant, tenant.userIds.owner);
      const events = recordEvents("member.suspended");

      await expect(
        memberService.suspendMember(tenant.actors.owner, {
          orgId: tenant.org.id,
          memberId: ownerId,
        }),
      ).rejects.toThrow(/yourself/);
      await expect(
        memberService.suspendMember(tenant.actors.admin, {
          orgId: tenant.org.id,
          memberId: ownerId,
        }),
      ).rejects.toThrow(/owner role/);
      events.stop();

      expect(events.seen).toHaveLength(0);
      await expect(memberRepo.findMemberById(tenant.org.id, ownerId)).resolves.toMatchObject({
        status: "active",
      });
    });

    it("requires member:remove on the target", async () => {
      const tenant = await createTenant("suspend-permission", "growth");
      const adminId = await memberIdOf(tenant, tenant.userIds.admin);

      await expect(
        memberService.suspendMember(tenant.actors.member, {
          orgId: tenant.org.id,
          memberId: adminId,
        }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    });

    it("changes nothing when suspending a suspended member or reinstating an active one", async () => {
      const tenant = await createTenant("suspend-idempotent", "growth");
      const viewerId = await memberIdOf(tenant, tenant.userIds.viewer);
      const suspendEvents = recordEvents("member.suspended");
      const reinstateEvents = recordEvents("member.reinstated");

      const first = await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      const again = await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      expect(again).toEqual(first);

      const reinstated = await memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      const reinstatedAgain = await memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      expect(reinstatedAgain).toEqual(reinstated);

      suspendEvents.stop();
      reinstateEvents.stop();
      expect(suspendEvents.seen).toHaveLength(1);
      expect(reinstateEvents.seen).toHaveLength(1);
    });

    it("refuses a member id that belongs to another workspace", async () => {
      const home = await createTenant("suspend-scope-home", "growth");
      const away = await createTenant("suspend-scope-away", "growth");
      const awayViewerId = await memberIdOf(away, away.userIds.viewer);

      await expect(
        memberService.suspendMember(home.actors.owner, {
          orgId: away.org.id,
          memberId: awayViewerId,
        }),
      ).rejects.toBeInstanceOf(TenantScopeError);
    });

    it("treats a removed membership as not found, and removal still frees the seat", async () => {
      const tenant = await createTenant("suspend-removed", "growth");
      const viewerId = await memberIdOf(tenant, tenant.userIds.viewer);
      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });

      await expect(
        memberService.suspendMember(tenant.actors.owner, {
          orgId: tenant.org.id,
          memberId: viewerId,
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
      await expect(
        memberService.reinstateMember(tenant.actors.owner, {
          orgId: tenant.org.id,
          memberId: viewerId,
        }),
      ).rejects.toBeInstanceOf(NotFoundError);

      await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(3);
      await expect(
        memberRepo.findSuspendedUserIds(tenant.org.id, [tenant.userIds.viewer]),
      ).resolves.toEqual(new Set());
    });
  });

  describe("the last owner", () => {
    it("refuses to suspend the only owner who is not suspended", async () => {
      const tenant = await createTenant("suspend-last-owner", "growth");
      const ownerId = await memberIdOf(tenant, tenant.userIds.owner);

      await expect(
        memberService.suspendMember(await staffActor(tenant, "owner"), {
          orgId: tenant.org.id,
          memberId: ownerId,
        }),
      ).rejects.toThrow(/at least one owner/);
      await expect(memberRepo.findMemberById(tenant.org.id, ownerId)).resolves.toMatchObject({
        status: "active",
      });
    });

    it("does not count a suspended owner as keeping the workspace ownable", async () => {
      const tenant = await createTenant("suspend-second-owner", "growth");
      const ownerId = await memberIdOf(tenant, tenant.userIds.owner);
      const adminId = await memberIdOf(tenant, tenant.userIds.admin);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: adminId,
        role: "owner",
      });
      await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: adminId,
      });

      await expect(
        memberService.suspendMember(await staffActor(tenant, "owner"), {
          orgId: tenant.org.id,
          memberId: ownerId,
        }),
      ).rejects.toThrow(/at least one owner/);
      await expect(
        memberService.updateMemberRole(await staffActor(tenant, "owner"), {
          orgId: tenant.org.id,
          memberId: ownerId,
          role: "admin",
        }),
      ).rejects.toThrow(/at least one owner/);

      // Reinstating the other owner restores a second owner who is not suspended.
      await memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: adminId,
      });
      await expect(
        memberService.suspendMember(await staffActor(tenant, "owner"), {
          orgId: tenant.org.id,
          memberId: ownerId,
        }),
      ).resolves.toMatchObject({ status: "suspended" });
    });
  });

  describe("while suspended", () => {
    it("cannot act, and the workspace is not listed for them", async () => {
      const tenant = await createTenant("suspend-access", "growth");
      const viewerUserId = tenant.userIds.viewer;
      const viewerId = await memberIdOf(tenant, viewerUserId);
      const principal = {
        userId: viewerUserId,
        email: `viewer@${tenant.org.slug}.test`,
        activeOrgId: null,
        expiresAt: toIsoTimestamp(new Date(Date.now() + 24 * 3_600_000)),
      };

      await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });

      await expect(memberService.resolveActor(viewerUserId, tenant.org.id)).resolves.toBeNull();
      await expect(
        sessionService.resolveActorForOrg(principal, tenant.org.slug),
      ).resolves.toBeNull();
      const orgIds = (await organizationService.listOrganizationsForUser(viewerUserId)).map(
        (org) => org.id,
      );
      expect(orgIds).not.toContain(tenant.org.id);
    });

    it("cannot be given new work, but keeps the work already assigned to them", async () => {
      const tenant = await createTenant("suspend-work", "growth");
      const adminUserId = tenant.userIds.admin;
      const assigned = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Assigned before suspension",
          assigneeId: adminUserId,
        }),
      );
      const unassigned = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Waiting for an assignee" }),
      );
      await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: await memberIdOf(tenant, adminUserId),
      });

      const createdEvents = recordEvents("issue.created");
      const assignedEvents = recordEvents("issue.assigned");
      const issuesBefore = await issueRepo.countIssues(tenant.org.id, tenant.project.id);

      await expect(
        issueService.createIssue(
          tenant.actors.member,
          issueInput(tenant.org.id, tenant.project.id, {
            title: "Created for a suspended assignee",
            assigneeId: adminUserId,
          }),
        ),
      ).rejects.toBeInstanceOf(MemberSuspendedError);
      await expect(
        issueService.assignIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: unassigned.id,
          assigneeId: adminUserId,
        }),
      ).rejects.toBeInstanceOf(MemberSuspendedError);
      createdEvents.stop();
      assignedEvents.stop();

      expect(createdEvents.seen).toHaveLength(0);
      expect(assignedEvents.seen).toHaveLength(0);
      await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(
        issuesBefore,
      );

      await expect(
        issueRepo.findIssueById(tenant.org.id, assigned.id),
      ).resolves.toMatchObject({ assigneeId: adminUserId });
      await expect(
        issueService.assignIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: assigned.id,
          assigneeId: null,
        }),
      ).resolves.toMatchObject({ assigneeId: null });
      await expect(
        issueService.assignIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: assigned.id,
          assigneeId: tenant.userIds.viewer,
        }),
      ).resolves.toMatchObject({ assigneeId: tenant.userIds.viewer });
    });

    it("cannot be mentioned: the handle does not resolve and a supplied id is dropped", async () => {
      const tenant = await createTenant("suspend-mention", "growth");
      const viewerUserId = tenant.userIds.viewer;
      await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: await memberIdOf(tenant, viewerUserId),
      });
      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Mention target" }),
      );

      const events = recordEvents("comment.created");
      const comment = await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "Looping in @viewer and @admin",
        parentId: null,
        mentionedUserIds: [viewerUserId],
      });
      events.stop();

      expect(comment.mentionedUserIds).toEqual([tenant.userIds.admin]);
      expect(events.seen).toEqual([
        expect.objectContaining({ mentionedUserIds: [tenant.userIds.admin] }),
      ]);

      const inbox = await notificationService.listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: viewerUserId,
        unreadOnly: false,
        kind: ["comment_mention"],
        limit: 25,
        cursor: null,
      });
      expect(inbox.items).toHaveLength(0);
    });

    it("receives no notification from the event fan-out or from notify()", async () => {
      const tenant = await createTenant("suspend-notify", "growth");
      const viewerUserId = tenant.userIds.viewer;
      await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: await memberIdOf(tenant, viewerUserId),
      });
      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Fan-out target" }),
      );

      await emit("issue.assigned", {
        orgId: tenant.org.id,
        actorId: tenant.userIds.owner,
        occurredAt: issue.createdAt,
        issueId: issue.id,
        projectId: issue.projectId,
        previousAssigneeId: null,
        assigneeId: viewerUserId,
      });
      const sent = await notificationService.notify(
        tenant.org.id,
        "comment_mention",
        [viewerUserId],
        {
          title: "You were mentioned",
          body: "Sent directly",
          href: `/issues/${issue.id}`,
          actorId: tenant.userIds.owner,
        },
      );

      expect(sent).toEqual([]);
      const inbox = await notificationService.listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: viewerUserId,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      });
      expect(inbox.items).toHaveLength(0);
    });

    it("is skipped by the daily digest, and digests unread notifications once reinstated", async () => {
      const tenant = await createTenant("suspend-digest", "growth");
      const viewerUserId = tenant.userIds.viewer;
      const viewerId = await memberIdOf(tenant, viewerUserId);
      await preferenceRepo.upsertPreference({
        orgId: tenant.org.id,
        userId: viewerUserId,
        kind: "comment_created",
        inApp: false,
        email: false,
        digestOnly: true,
      });
      await notificationRepo.insertNotification(tenant.org.id, {
        orgId: tenant.org.id,
        recipientId: viewerUserId,
        kind: "comment_created",
        title: "Still unread",
        body: "Kept while suspended",
        href: "/issues/1",
        actorId: null,
        channels: ["email"],
      });
      const windowStart = toIsoTimestamp(new Date(Date.now() - 24 * 3_600_000));
      const windowEnd = toIsoTimestamp(new Date(Date.now() + 3_600_000));

      await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      expect(await digestService.listDigestRecipients(tenant.org.id)).not.toContain(viewerUserId);
      await expect(
        digestService.buildDigest(tenant.org.id, viewerUserId, windowStart, windowEnd),
      ).resolves.toBeNull();

      await memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      expect(await digestService.listDigestRecipients(tenant.org.id)).toContain(viewerUserId);
      const bundle = await digestService.buildDigest(
        tenant.org.id,
        viewerUserId,
        windowStart,
        windowEnd,
      );
      expect(bundle?.entries.map((entry) => entry.title)).toEqual(["Still unread"]);
    });
  });

  describe("reinstatement", () => {
    it("restores access, new work and mentions", async () => {
      const tenant = await createTenant("reinstate-restores", "growth");
      const viewerUserId = tenant.userIds.viewer;
      const viewerId = await memberIdOf(tenant, viewerUserId);
      await memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });
      await memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerId,
      });

      await expect(memberService.resolveActor(viewerUserId, tenant.org.id)).resolves.toEqual({
        userId: viewerUserId,
        orgId: tenant.org.id,
        role: "viewer",
      });
      const orgIds = (await organizationService.listOrganizationsForUser(viewerUserId)).map(
        (org) => org.id,
      );
      expect(orgIds).toContain(tenant.org.id);

      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "After reinstatement" }),
      );
      await expect(
        issueService.assignIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          assigneeId: viewerUserId,
        }),
      ).resolves.toMatchObject({ assigneeId: viewerUserId });

      const comment = await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "Over to @viewer",
        parentId: null,
        mentionedUserIds: [],
      });
      expect(comment.mentionedUserIds).toEqual([viewerUserId]);
    });
  });
});
